corpus_block("test-geom-hline-vline-abline.R: check h/v/abline transformed on basic projections", {
  dat <- data_frame(x = LETTERS[1:5], y = 1:5)
  .plot("test-geom-hline-vline-abline.R: check h/v/abline transformed on basic projections #1", plot <- ggplot(dat, aes(x, y)) +
      geom_col(width = 1) +
      geom_point() +
      geom_vline(xintercept = 3, colour = "red") +
      geom_hline(yintercept = 3, colour = "blue") +
      geom_abline(intercept = 0, slope = 1, colour = "purple") +
      labs(x = NULL, y = NULL))
  .plot("test-geom-hline-vline-abline.R: check h/v/abline transformed on basic projections #2", plot + coord_cartesian(expand = FALSE))
  .plot("test-geom-hline-vline-abline.R: check h/v/abline transformed on basic projections #3", plot + coord_flip())
  .plot("test-geom-hline-vline-abline.R: check h/v/abline transformed on basic projections #4", plot + coord_polar())
})

corpus_block("test-geom-hline-vline-abline.R: geom_abline is clipped to x/y ranges", {
  df <- data.frame(slope = c(-0.2, -1, -5, 5, 1, 0.2))
  .plot("test-geom-hline-vline-abline.R: geom_abline is clipped to x/y ranges #1", p <- ggplot(df) +
      geom_abline(aes(slope = slope, intercept = 0)) +
      scale_x_continuous(limits = c(-1, 1), expand = FALSE) +
      scale_y_continuous(limits = c(-1, 1), expand = FALSE) +
      coord_cartesian(clip = "off"))
  data <- layer_grob(p)[[1]]
  x <- c(as.numeric(data$x0), as.numeric(data$x1))
  y <- c(as.numeric(data$y0), as.numeric(data$y1))
})

